 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    # The rare color marks destinations; the remaining non-background cells
    # form the small sprite to stamp at each destination.
    marker = min(colors, key=lambda v: sum(row.count(v) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    sprite_cells = [(r, c) for r in range(h) for c in range(w)
                    if grid[r][c] != bg and grid[r][c] != marker]
    if not points or not sprite_cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in sprite_cells); r1 = max(r for r, c in sprite_cells)
    c0 = min(c for r, c in sprite_cells); c1 = max(c for r, c in sprite_cells)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    sprite = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    out = [row[:] for row in grid]
    for r, c in points:
        out[r][c] = bg
    for r, c in points:
        for i, row in enumerate(sprite):
            for j, value in enumerate(row):
                rr, cc = r + i - (ar - r0), c + j - (ac - c0)
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
